export const READINESS_STATUS_LABELS: Record<string, LocalizedPair> = {
  ready: { en: 'Ready', hi: 'तैयार' },
  in_progress: { en: 'In progress', hi: 'प्रगति में' },
  not_started: { en: 'Not started', hi: 'शुरू नहीं' },
  prep_draft: { en: 'Prep draft', hi: 'तैयारी ड्राफ़्ट' },
  readiness_assessment: { en: 'Assurance prep', hi: 'आश्वासन तैयारी' },
  filing_ready: { en: 'Filing ready', hi: 'फाइलिंग के लिए तैयार' },
  registry_ready: { en: 'Registry ready', hi: 'रजिस्ट्री तैयार' },
  gap: { en: 'Gap open', hi: 'अंतराल खुला' },
  missing_fields: { en: 'Missing fields', hi: 'फ़ील्ड अधूरे' },
};

export const resolveTrackItemLabel = (key: string, locale: ReadinessLocale, fallback = key): string => (
  TRACK_ITEM_LABELS[key]?.[locale] || TRACK_ITEM_LABELS[key]?.en || fallback
);

export const resolveReadinessStatusLabel = (
  status: string | undefined,
  locale: ReadinessLocale,
  fallback?: string
): string => {
  const normalized = String(status || '').toLowerCase();
  return READINESS_STATUS_LABELS[normalized]?.[locale]
    || READINESS_STATUS_LABELS[normalized]?.en
    || fallback
    || status
    || 'Unknown';
};
