export interface DailyTaskRoute {
  path: string;
  actionLabel: string;
}

const DAILY_TASK_ROUTES: Record<string, DailyTaskRoute> = {
  'upload-transactions': {
    path: '/document-upload',
    actionLabel: 'Upload documents',
  },
  'run-assessment': {
    path: '/carbon-footprint?section=start-assessment',
    actionLabel: 'Start assessment',
  },
  'implement-reco': {
    path: '/carbon-footprint?section=recommendations',
    actionLabel: 'View recommendations',
  },
};

export function getDailyTaskRoute(taskId: string): DailyTaskRoute {
  return (
    DAILY_TASK_ROUTES[taskId] ?? {
      path: '/dashboard',
      actionLabel: 'Go to dashboard',
    }
  );
}
