export const MSME_HIDE_REPORTING_PANELS = {
  remediationTrackDetails: true,
  agentAdvisoryDetails: true,
  blendedScoreBreakdown: true,
  sectorLensAlert: true,
} as const;

export const msmeSimplifiedActionLabel = (action: string, dataFeedSatisfied?: boolean): string => {
  if (!dataFeedSatisfied) {
    return action;
  }
  if (/upload/i.test(action)) {
    return action.replace(/upload/gi, 'Review');
  }
  return action;
};
