import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('token')}` });

const PartnerMsmeCohortPanel: React.FC = () => {
  const [items, setItems] = useState<Array<Record<string, unknown>>>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(buildApiUrl('/partner-account/msmes'), {
        headers: authHeaders(),
        params: search ? { search } : {},
      });
      setItems(res.data?.data?.items || []);
    } catch (e) {
      setError(axios.isAxiosError(e) ? e.response?.data?.message || e.message : 'Failed to load cohort');
      setItems([]);
    } finally {
      setLoading(false);
    }
  }, [search]);

  useEffect(() => {
    load();
  }, [load]);

  return (
    <Box>
      <Stack direction="row" spacing={1} sx={{ mb: 2 }}>
        <TextField size="small" placeholder="Search company" value={search} onChange={(e) => setSearch(e.target.value)} />
        <Button variant="contained" onClick={load}>Search</Button>
      </Stack>
      {error ? <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert> : null}
      {loading ? <CircularProgress /> : (
        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Company</TableCell>
                <TableCell>Industry</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Carbon</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {items.map((row) => (
                <TableRow key={String(row.id)}>
                  <TableCell>{String(row.companyName || '—')}</TableCell>
                  <TableCell>{String(row.industry || '—')}</TableCell>
                  <TableCell><Chip size="small" label={String(row.status || '—')} /></TableCell>
                  <TableCell>{(row.carbon as { carbonScore?: number })?.carbonScore ?? '—'}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Box>
  );
};

export default PartnerMsmeCohortPanel;
